import { test, expect } from '@playwright/test';

test.describe('Search Spelling Tolerance', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should find results with single character typo', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('speling');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

    const results = page.getByRole('region', { name: /search results/i });
    await expect(results).toBeVisible();

    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);
  });

  test('should find results with transposed characters', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    await searchInput.fill('recieve');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    await page.waitForLoadState('networkidle');

